//! Building an image holds the tree's metadata in memory, never its file
//! data. 192 MiB of file content, generated by readers as it is read and
//! written to a file, must be built with a peak heap far below its size.
//!
//! The counter is the global allocator's, so this is the only test in its
//! binary: another test running beside it would add its own allocations.

mod common;

use common::open_image;
use fs_erofs::mkfs::{
    self, BuildOptions, Compression, Content, Node, NodeMeta, DEFAULT_DIR_MODE, DEFAULT_FILE_MODE,
};
use std::alloc::{GlobalAlloc, Layout, System};
use std::collections::BTreeMap;
use std::io::Read;
use std::sync::atomic::{AtomicUsize, Ordering};

struct Peak;

static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);

unsafe impl GlobalAlloc for Peak {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let live = LIVE.fetch_add(layout.size(), Ordering::Relaxed) + layout.size();
        PEAK.fetch_max(live, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Ordering::Relaxed);
        unsafe { System.dealloc(ptr, layout) }
    }
}

#[global_allocator]
static GLOBAL: Peak = Peak;

/// Bytes made as they are read: xorshift, so they do not compress and
/// nothing holds them.
struct Generated {
    state: u64,
    left: u64,
}

impl Read for Generated {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let n = buf.len().min(self.left as usize);
        for b in &mut buf[..n] {
            self.state ^= self.state << 13;
            self.state ^= self.state >> 7;
            self.state ^= self.state << 17;
            *b = self.state as u8;
        }
        self.left -= n as u64;
        Ok(n)
    }
}

fn generated(seed: u64, size: u64) -> Node {
    Node::StreamedFile {
        mode: DEFAULT_FILE_MODE,
        content: Content::new(size, move || {
            Ok(Generated {
                state: seed | 1,
                left: size,
            })
        }),
        meta: NodeMeta::default(),
        xattrs: Vec::new(),
    }
}

fn directory(entries: BTreeMap<String, Node>) -> Node {
    Node::Dir {
        mode: DEFAULT_DIR_MODE,
        entries,
        meta: NodeMeta::default(),
        xattrs: Vec::new(),
    }
}

const BIG_FILES: u64 = 48;
const BIG_SIZE: u64 = 4 << 20;
const SMALL_FILES: u64 = 10_000;
/// The bound on the build's peak heap: an eighth of the file data.
const PEAK_LIMIT: usize = 24 << 20;

fn tree() -> Node {
    let mut root = BTreeMap::new();
    for d in 0..100u64 {
        let mut entries = BTreeMap::new();
        for f in 0..SMALL_FILES / 100 {
            let seed = d * 1000 + f;
            entries.insert(format!("small-{f:03}"), generated(seed, 64 + seed % 137));
        }
        root.insert(format!("dir-{d:03}"), directory(entries));
    }
    for b in 0..BIG_FILES {
        root.insert(format!("big-{b:02}"), generated(1_000_000 + b, BIG_SIZE));
    }
    directory(root)
}

/// Uncompressed, and compressed as `-zlz4hc,12 -C 32768` on one thread
/// and on four. Compression adds segments in flight -- one more than the
/// threads, each a 4 MiB segment and its output -- and nothing per byte of
/// data.
#[test]
fn a_build_holds_the_metadata_in_memory_and_never_the_file_data() {
    build_and_check(None, 1);
    build_and_check(Some(Compression::LZ4HC_12_32K), 1);
    build_and_check(Some(Compression::LZ4HC_12_32K), 4);
}

/// What each segment in flight may hold: its 4 MiB of input, and its
/// output, which is never larger.
const PER_SEGMENT: usize = 8 << 20;

fn build_and_check(compression: Option<Compression>, threads: usize) {
    let tree = tree();
    let options = BuildOptions {
        compression,
        threads,
        ..BuildOptions::default()
    };
    let limit = if threads > 1 {
        PEAK_LIMIT + (threads + 1) * PER_SEGMENT
    } else {
        PEAK_LIMIT
    };
    let mut sink = tempfile::tempfile().expect("a file to build into");
    let before = LIVE.load(Ordering::SeqCst);
    PEAK.store(before, Ordering::SeqCst);
    let len = mkfs::build_image_to(tree, 12, options, &mut sink).expect("build");
    let peak = PEAK.load(Ordering::SeqCst) - before;

    assert!(
        len > BIG_FILES * BIG_SIZE,
        "the image holds the data ({len} bytes)"
    );
    assert!(
        peak < limit,
        "building an image of {} MiB of file data ({compression:?}, {threads} threads) peaked \
         at {} MiB of heap; the limit is {} MiB",
        (BIG_FILES * BIG_SIZE) >> 20,
        peak >> 20,
        limit >> 20
    );

    // And it is the image the tree described.
    let mut img = Vec::new();
    use std::io::Seek;
    sink.rewind().unwrap();
    sink.read_to_end(&mut img).unwrap();
    let fs = open_image(img);
    for (path, seed, size) in [
        ("/big-00".to_string(), 1_000_000u64, BIG_SIZE),
        (
            format!("/big-{:02}", BIG_FILES - 1),
            1_000_000 + BIG_FILES - 1,
            BIG_SIZE,
        ),
        ("/dir-042/small-007".to_string(), 42_007, 64 + 42_007 % 137),
    ] {
        let inode = fs.lookup_path(&path).unwrap();
        assert_eq!(inode.size, size, "{path}");
        let mut want = vec![0u8; size as usize];
        Generated {
            state: seed | 1,
            left: size,
        }
        .read_exact(&mut want)
        .unwrap();
        let mut got = vec![0u8; size as usize];
        fs.read_file(&inode, 0, &mut got).unwrap();
        assert!(got == want, "{path} reads back other bytes");
    }
}
